// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 0, 100 ether);
        if (caller == address(0)) caller = address(1);

        vm.deal(caller, amount);

        uint256 before = c.pastBlockTime();

        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}('');
        ok = success;

        if (ok) {
            assertTrue(amount == 10 ether);
        } else {
            assertTrue(c.pastBlockTime() == before);
        }
    }
}
